#!/usr/bin/env bash
set -euo pipefail
artifact=${ARTIFACT_DIR:?}; mkdir -p "$artifact"; report="$artifact/build-report.md"; end=$(date +%s); start=${BUILD_START_EPOCH:-$end}
{ echo '# SukiSU Non-GKI build report'; echo; echo "- 编译内核的名字: ${KERNEL_NAME:-by_XiZi}"; echo "- 内核版本: ${KERNEL_RELEASE:-unknown} (源码 ${KERNEL_VERSION_CODE:-unknown})"; echo "- 纯净内核源码仓库名字: ${KERNEL_SOURCE_NAME:-unknown}"; echo "- 编译总时间: $((end-start)) 秒"; echo "- 集成选择: SukiSU Ultra=是; SUSFS=${INTEGRATE_SUSFS:-false}; DroidSpaces=${INTEGRATE_DROIDSPACES:-false}; LTO关闭=${DISABLE_LTO:-false}; A/B=${AB_PARTITION:-false}; AK3=${PACKAGE_AK3:-false}"; echo; echo '## 产物校验'; echo '| 文件 | 大小 | SHA-256 |'; echo '| --- | ---: | --- |'; while IFS= read -r -d '' file; do printf '| `%s` | %s | `%s` |\n' "${file#$artifact/}" "$(du -h "$file" | cut -f1)" "$(sha256sum "$file" | cut -d' ' -f1)"; done < <(find "$artifact" -type f ! -path "$report" -print0 | sort -z); } > "$report"
if [[ -n "${GITHUB_STEP_SUMMARY:-}" ]]; then cat "$report" >> "$GITHUB_STEP_SUMMARY"; else cat "$report"; fi
